## iOS Widget 调试

### Xcode Preview 实时预览

SwiftUI 的 Preview 功能同样适用于 widget 视图，可以在不同状态和尺寸下实时预览：

```swift
// 在 Widget 视图文件中添加 Preview
struct WeatherWidgetView: View {
    var entry: WeatherEntry

    var body: some View {
        // ... widget 视图代码
    }
}

#Preview("Small - 晴天") {
    WeatherWidgetView(entry: .snapshotPreview)
        .previewContext(WidgetPreviewContext(family: .systemSmall))
        .containerBackground(for: .widget) {
            Color(.systemBackground)
        }
}

#Preview("Medium - 多云") {
    WeatherWidgetView(entry: WeatherEntry(
        date: Date(),
        temperature: 18,
        condition: "多云",
        symbolName: "cloud.fill",
        location: "上海",
        hourlyForecast: [],
        high: 22,
        low: 15,
        humidity: 65,
        isPlaceholder: false
    ))
    .previewContext(WidgetPreviewContext(family: .systemMedium))
    .containerBackground(for: .widget) {
        Color(.systemBackground)
    }
}

#Preview("Large - 雨天") {
    WeatherWidgetView(entry: WeatherEntry(
        date: Date(),
        temperature: 12,
        condition: "小雨",
        symbolName: "cloud.rain.fill",
        location: "广州",
        hourlyForecast: [
            HourlyForecast(time: Date(), temp: 12, symbolName: "cloud.rain.fill"),
            HourlyForecast(time: Date().addingTimeInterval(3600), temp: 13, symbolName: "cloud.fill"),
            HourlyForecast(time: Date().addingTimeInterval(7200), temp: 14, symbolName: "cloud.sun.fill")
        ],
        high: 15,
        low: 10,
        humidity: 85,
        isPlaceholder: false
    ))
    .previewContext(WidgetPreviewContext(family: .systemLarge))
    .containerBackground(for: .widget) {
        Color(.systemBackground)
    }
}

#Preview("锁屏 - Circular") {
    LockScreenWeatherView(entry: .snapshotPreview)
        .previewContext(WidgetPreviewContext(family: .accessoryCircular))
}

#Preview("深色模式") {
    WeatherWidgetView(entry: .snapshotPreview)
        .previewContext(WidgetPreviewContext(family: .systemMedium))
        .preferredColorScheme(.dark)
        .containerBackground(for: .widget) {
            Color(.systemBackground)
        }
}
```

### WidgetPreviewContext 尺寸

| PreviewContext                                        | 对应尺寸家族 |
| :---------------------------------------------------- | :----------- |
| `WidgetPreviewContext(family: .systemSmall)`          | 2x2 主屏     |
| `WidgetPreviewContext(family: .systemMedium)`         | 4x2 主屏     |
| `WidgetPreviewContext(family: .systemLarge)`          | 4x4 主屏     |
| `WidgetPreviewContext(family: .accessoryCircular)`    | 锁屏圆形     |
| `WidgetPreviewContext(family: .accessoryRectangular)` | 锁屏矩形     |
| `WidgetPreviewContext(family: .accessoryInline)`      | 状态栏文本   |

### 调试 Widget 进程

Widget 扩展运行在独立进程中，需要单独附加调试器：

1. 在 Xcode 中选择 widget extension 的 scheme
2. 点击 Run（或按 Cmd+R）
3. Xcode 会询问要运行哪个应用，选择你的主应用
4. 主应用启动后，添加 widget 到主屏
5. 当 widget 被渲染时，调试器会自动附加

或者手动附加：

- Xcode → Debug → Attach to Process by PID or Name
- 输入 widget extension 的 bundle ID 或进程名

### Console 日志查看

在 widget 代码中使用 `print` 或 `os_log` 输出日志，通过 Console.app 查看：

```swift
import os.log

let widgetLog = OSLog(subsystem: "com.example.myapp.widget", category: "Widget")

func getTimeline(in context: Context, completion: @escaping (Timeline<WeatherEntry>) -> Void) {
    os_log("getTimeline called, family: %{public}@",
           log: widgetLog, type: .debug,
           context.family.rawValue)

    WeatherAPI.shared.fetch { result in
        switch result {
        case .success(let data):
            os_log("Weather data fetched: %{public}d items",
                   log: widgetLog, type: .info,
                   data.hourly.count)
            // ...
        case .failure(let error):
            os_log("Weather fetch failed: %{public}@",
                   log: widgetLog, type: .error,
                   error.localizedDescription)
            // ...
        }
    }
}
```

在 Console.app 中：

- 选择你的设备
- 在搜索栏输入 `subsystem:com.example.myapp.widget`
- 可以看到所有 widget 相关的日志

### 控制 Widget 刷新

使用 `WidgetCenter` 主动触发刷新，方便调试：

```swift
// 在主应用中添加调试按钮
#if DEBUG
Button("刷新所有 Widget") {
    WidgetCenter.shared.reloadAllTimelines()
}

Button("刷新天气 Widget") {
    WidgetCenter.shared.reloadTimelines(ofKind: "WeatherWidget")
}

Button("打印当前 Widget 信息") {
    WidgetCenter.shared.getCurrentConfigurations { result in
        switch result {
        case .success(let configs):
            for config in configs {
                print("Widget: \(config.kind)")
                print("  Family: \(config.family.rawValue)")
                print("  Config: \(config.configuration)")
            }
        case .failure(let error):
            print("Error: \(error)")
        }
    }
}
#endif
```

