## iOS 实时活动调试

### 启动和观察实时活动

```swift
// 在主应用中添加调试控制
#if DEBUG
struct LiveActivityDebugView: View {
    var body: some View {
        VStack(spacing: 16) {
            Button("启动配送实时活动") {
                startDeliveryActivity()
            }

            Button("更新为配送中") {
                updateActivityToDelivering()
            }

            Button("更新为已送达") {
                updateActivityToArrived()
            }

            Button("结束活动") {
                endAllActivities()
            }

            Button("打印活动列表") {
                let activities = Activity<DeliveryAttributes>.activities
                print("当前活动数: \(activities.count)")
                for activity in activities {
                    print("  ID: \(activity.id)")
                    print("  State: \(activity.activityState)")
                    print("  Content: \(activity.content.state)")
                }
            }
        }
    }
}
#endif
```

### 模拟推送更新

在 Xcode 中创建 `.apns` 文件模拟 APNs 推送：

```json
// DeliveryLiveActivity.apns
{
  "aps": {
    "timestamp": 1719990000,
    "event": "update",
    "content-state": {
      "status": "delivering",
      "estimatedDeliveryTime": 1719993600,
      "riderName": "李师傅",
      "riderDistance": 850.0
    },
    "alert": {
      "title": "骑手正在配送",
      "body": "李师傅距您 850 米"
    }
  }
}
```

在 Simulator 中，将 `.apns` 文件拖到模拟器窗口即可触发推送更新（需要先获取实时活动的 pushToken 并配置到文件中）。

