## 单元测试

### iOS TimelineProvider 测试

```swift
import XCTest
@testable import MyWidgetExtension

class WeatherProviderTests: XCTestCase {

    var provider: WeatherProvider!
    var mockAPI: MockWeatherAPI!

    override func setUp() {
        super.setUp()
        mockAPI = MockWeatherAPI()
        provider = WeatherProvider(api: mockAPI)
    }

    // 测试 placeholder 返回正确的数据
    func testPlaceholder() {
        let context = Context(family: .systemMedium, isPreview: false)
        let entry = provider.placeholder(in: context)

        XCTAssertFalse(entry.isPlaceholder)
        XCTAssertEqual(entry.location, "北京")
        XCTAssertNotNil(entry.temperature)
    }

    // 测试 getSnapshot 使用缓存
    func testGetSnapshotUsesCache() {
        let expectation = expectation(description: "snapshot")
        let context = Context(family: .systemSmall, isPreview: false)

        provider.getSnapshot(in: context) { entry in
            XCTAssertEqual(entry.temperature, 22)
            expectation.fulfill()
        }

        wait(for: [expectation], timeout: 1.0)
    }

    // 测试 getTimeline 返回正确数量的 entry
    func testGetTimelineReturnsMultipleEntries() {
        let expectation = expectation(description: "timeline")
        let context = Context(family: .systemMedium, isPreview: false)

        mockAPI.mockResponse = WeatherResponse(
            current: CurrentWeather(temp: 22, condition: "晴", symbol: "sun.max.fill"),
            location: "北京",
            hourly: [],
            daily: []
        )

        provider.getTimeline(in: context) { timeline in
            XCTAssertGreaterThan(timeline.entries.count, 1)
            // 验证第一条 entry 的时间是当前时间
            let firstEntry = timeline.entries[0]
            XCTAssertEqual(
                Calendar.current.component(.hour, from: firstEntry.date),
                Calendar.current.component(.hour, from: Date())
            )
            expectation.fulfill()
        }

        wait(for: [expectation], timeout: 5.0)
    }

    // 测试网络失败时的降级
    func testGetTimelineNetworkFailure() {
        let expectation = expectation(description: "timeline failure")
        let context = Context(family: .systemSmall, isPreview: false)

        mockAPI.shouldFail = true

        provider.getTimeline(in: context) { timeline in
            XCTAssertEqual(timeline.entries.count, 1)
            // 验证刷新策略是短时间后重试
            if case .after(let date) = timeline.policy {
                let interval = date.timeIntervalSinceNow
                XCTAssertLessThan(interval, 10 * 60)  // 10 分钟内重试
                XCTAssertGreaterThan(interval, 0)
            }
            expectation.fulfill()
        }

        wait(for: [expectation], timeout: 5.0)
    }
}

// Mock API
class MockWeatherAPI: WeatherAPIService {
    var mockResponse: WeatherResponse?
    var shouldFail = false

    func fetch(completion: @escaping (Result<WeatherResponse, Error>) -> Void) {
        if shouldFail {
            completion(.failure(NSError(domain: "test", code: -1)))
        } else if let response = mockResponse {
            completion(.success(response))
        }
    }
}
```

### Android Glance 状态测试

```kotlin
class WeatherWidgetTest {

    @Test
    fun `widget state maps correctly from API response`() {
        val apiResponse = WeatherResponse(
            current = CurrentWeather(temp = 22, condition = "晴"),
            location = "北京",
            lastUpdated = 1719990000000
        )

        val state = apiResponse.toWidgetState()

        assertEquals(22, state.temperature)
        assertEquals("晴", state.condition)
        assertEquals("北京", state.location)
    }

    @Test
    fun `expired state triggers refresh`() {
        val expiredState = WeatherWidgetState(
            temperature = 22,
            condition = "晴",
            lastUpdated = System.currentTimeMillis() - 60 * 60 * 1000  // 1 小时前
        )

        assertTrue(isStateExpired(expiredState))
    }

    @Test
    fun `fresh state does not trigger refresh`() {
        val freshState = WeatherWidgetState(
            temperature = 22,
            condition = "晴",
            lastUpdated = System.currentTimeMillis() - 10 * 60 * 1000  // 10 分钟前
        )

        assertFalse(isStateExpired(freshState))
    }
}
```

