## 快照测试

### iOS 快照测试

使用 `iOSSnapshotTestKit` 或自定义方案验证 widget 在不同状态下的渲染：

```swift
import SnapshotTesting
import SwiftUI
@testable import MyWidgetExtension

class WeatherWidgetSnapshotTests: XCTestCase {

    func testSmallWidgetSunny() {
        let view = WeatherWidgetView(entry: .snapshotPreview)
            .previewContext(WidgetPreviewContext(family: .systemSmall))
            .containerBackground(for: .widget) { Color(.systemBackground) }

        let viewController = UIHostingController(rootView: view)
        viewController.view.frame = CGRect(x: 0, y: 0, width: 169, height: 169)

        assertSnapshot(of: viewController, as: .image)
    }

    func testMediumWidgetDarkMode() {
        let view = WeatherWidgetView(entry: .snapshotPreview)
            .previewContext(WidgetPreviewContext(family: .systemMedium))
            .preferredColorScheme(.dark)
            .containerBackground(for: .widget) { Color(.systemBackground) }

        let viewController = UIHostingController(rootView: view)
        viewController.view.frame = CGRect(x: 0, y: 0, width: 360, height: 169)

        assertSnapshot(of: viewController, as: .image)
    }

    func testLockScreenWidget() {
        let view = LockScreenWeatherView(entry: .snapshotPreview)
            .previewContext(WidgetPreviewContext(family: .accessoryRectangular))

        let viewController = UIHostingController(rootView: view)
        viewController.view.frame = CGRect(x: 0, y: 0, width: 160, height: 60)

        assertSnapshot(of: viewController, as: .image)
    }
}
```

